from typing import List

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        m = len(p)
        target = sorted(p)
        ans = []
        for i in range(len(s) - m + 1):
            if sorted(s[i:i + m]) == target:
                ans.append(i)
        return ans

