from typing import List
from collections import Counter

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        m = len(p)
        if m > len(s):
            return []
        need = Counter(p)
        window = Counter(s[:m])
        ans = [0] if window == need else []
        for right in range(m, len(s)):
            old = s[right - m]
            window[old] -= 1
            if window[old] == 0:
                del window[old]
            window[s[right]] += 1
            if window == need:
                ans.append(right - m + 1)
        return ans

